let current='home',tabName='工作空间';
const $=s=>document.querySelector(s),icon=n=>`<i data-lucide="${n}"></i>`;
function icons(){lucide.createIcons()}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function closeModal(){$('#modal-bg').style.display='none'}function modal(html){$('#modal').innerHTML=`<button class="modal-close" aria-label="关闭" onclick="closeModal()">${icon('x')}</button>`+html;$('#modal-bg').style.display='grid';icons();$('#modal button').focus()}
function about(){modal('<h2 id="modal-title">全域运营 · 交互原型</h2><p>私域数字员工提供客户群发、运营统计、群聊查询和运营问答；抖音数字员工提供统一账号授权、需求驱动的视频创作、经营日报与直播素材诊断。</p><p>当前为本地示例，不连接业务服务、不发送消息。刷新会重置创作任务和文件；示例授权与日报配置保存在本浏览器，不代表真实授权或自动化。</p>')}
const info={home:['今日工作台','从一个具体需求开始，让数字员工帮你完成运营工作'],send:['客户群发','私域数字员工 / 向客户私聊发送 1 对 1 消息'],query:['运营统计','私域数字员工 / 客户增长、留存与触达效果'],groups:['群聊查询','私域数字员工 / 群聊、群主、成员与分组'],qa:['运营问答','私域数字员工 / 查找操作指引与问题依据'],authorize:['账号授权','抖音数字员工 / 抖音号与来客统一授权管理'],video:['视频创作','抖音数字员工 / 说需求、确认简报，再预览发布'],live:['直播素材诊断','抖音数字员工 / 登记链接、核查证据；自动抓流不可用'],monitor:['经营日报','抖音数字员工 / 销售、核销、内容、评价与自动推送配置'],files:['成果库','查看当前会话中的群发草案和视频创作方案']};
function head(key){return `<div class="page-head"><div class="eyebrow">全域运营工作台 / ${['send','query','groups','qa'].includes(key)?'私域数字员工':key==='home'||key==='files'?'工作空间':'抖音数字员工'}</div><div class="title-row"><h1>${info[key][0]}</h1><span class="badge">演示模式</span></div><div class="desc">${info[key][1]}</div><div class="tabs">${['工作空间','执行记录'].map(t=>`<button onclick="switchTab('${t}')" class="${tabName===t?'active':''}">${t}</button>`).join('')}</div></div>`}
function navigate(key){current=info[key]?key:'home';document.querySelector('.mobile-nav').value=current;tabName='工作空间';document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===current));document.querySelectorAll('[data-rail]').forEach(e=>e.classList.toggle('active',e.dataset.rail===(['send','query','groups','qa'].includes(current)?'send':['authorize','video','live','monitor'].includes(current)?'video':current)));render()}
function switchTab(t){tabName=t;render()}function render(){$('#main').innerHTML=head(current)+workspace();if(['authorize','video','live','monitor'].includes(current))renderDouyinRight();else renderPrivateRight();icons()}
function table(cols,rows){return `<div class="table-scroll"><table class="table"><thead><tr>${cols.map(c=>'<th scope="col">'+c+'</th>').join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${cols.length}" class="empty-table">没有符合条件的示例记录，请调整筛选。</td></tr>`}</tbody></table></div>`}
function metrics(items){return `<div class="metric-grid">${items.map(x=>`<div class="metric"><small>${x[0]}</small><strong>${x[1]}</strong><em>${x[2]}</em></div>`).join('')}</div>`}
function workspace(){if(['authorize','live','monitor'].includes(current))return dyWorkspace();if(current==='video')return videoWorkspace();if(['send','query','groups','qa'].includes(current))return privateWorkspace();if(tabName==='执行记录')return `<div class="workspace"><h2>当前会话记录</h2>${renderPrivateLogs()}</div>`;if(current==='home')return homeWorkspace();if(current==='files')return filesWorkspace();return ''; }
function homeWorkspace(){return `<div class="private-work"><div class="welcome-block"><div class="eyebrow">YOUR DIGITAL TEAM</div><h2>今天，先处理哪件事？</h2><p>选择员工的工作能力，直接进入对应流程。</p></div><div class="home-employee"><div class="avatar">${icon('users-round')}</div><div><h3>私域数字员工</h3><p>面向企微客户与社群的日常运营</p></div><span class="badge">4 项能力</span></div><div class="home-grid">${[['send','send','客户群发','说一句需求，自动准备整套预览'],['query','chart-no-axes-combined','运营统计','说出问题，自动整理统计结果'],['groups','messages-square','群聊查询','说出群或门店，自动定位结果'],['qa','book-open-text','运营问答','一句话问运营，查看有来源的答案']].map(([key,ic,title,desc])=>`<button class="home-capability" onclick="navigate('${key}')">${icon(ic)}<h3>${title}</h3><p>${desc}</p><span>进入工作空间 →</span></button>`).join('')}</div><div class="home-employee" style="margin-top:25px"><div class="avatar douyin">${icon('clapperboard')}</div><div><h3>抖音数字员工</h3><p>内容创作与门店经营支持</p></div><span class="badge">4 项能力</span></div><div class="home-grid douyin-grid">${[['authorize','key-round','账号授权','连接抖音与来客，明确门店范围'],['video','sparkles','视频创作','说需求，确认方案后预览发布'],['monitor','notebook-pen','经营日报','订单与验券汇总，未确认指标不开放'],['live','scan-eye','直播素材诊断','基于有权使用的证据，辅助复核']].map(([key,ic,title,desc])=>`<button class="home-capability" onclick="navigate('${key}')">${icon(ic)}<h3>${title}</h3><p>${desc}</p><span>进入工作空间 →</span></button>`).join('')}</div><p class="empty-note">当前为功能原型。所有客户和群聊均为虚构示例，不会触发真实业务操作。</p></div>`}
function filesWorkspace(){let drafts=privateState.drafts;return `<div class="private-work"><div class="video-card"><h3>客户群发草案 · ${drafts.length} 份</h3>${drafts.length?table(['草案','目标客户','状态','操作'],drafts.map(d=>[esc(d.name),d.count+' 人',d.cancelled?'已取消草案':'待业务接入',`<button class="link" onclick="viewSendDraft('${d.id}')">查看 →</button>`])):'<p class="empty-note">还没有保存的草案。完成客户范围预览后，可在这里查看。</p><button class="primary" onclick="navigate(\'send\')">准备客户群发</button>'}</div><div class="video-card"><h3>视频创作方案</h3><p class="hint">${videoFlow.prompt?'当前会话已有创作描述，可返回视频工作空间继续。':'在视频创作工作空间确认简报后查看。'}</p><button class="secondary" onclick="navigate('video')">进入视频创作 →</button></div></div>`}
$('#search').addEventListener('keydown',e=>{if(e.key!=='Enter')return;let q=e.target.value.trim();if(!q)return;let found=Object.entries(info).filter(([key,[name,desc]])=>(name+desc).includes(q));modal('<h2 id="modal-title">功能搜索</h2><p>关键词：'+esc(q)+'</p>'+(found.length?found.map(([key,[name]])=>`<button class="nav" onclick="closeModal();navigate('${key}')">${name} →</button>`).join(''):'<p>没有匹配的功能。可搜索“客户”“统计”“群聊”“问答”或“视频”。</p>'))});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
